#!/bin/bash

cd /app/src

export CI=true

# Copy HEAD test files from /tests (overwrites BASE state)
mkdir -p "test"
cp "/tests/index.test.js" "test/index.test.js"

# Create an HTTP mock that returns a fake DynamoDB Local tarball
# The real S3 URL returns 403, so we intercept the http.get call
# and serve a valid tar.gz containing a fake JAR file.
# This ensures the download path executes, making the code difference
# between bug (tar.Extract) and fix (tar.x) testable.
cat > /tmp/mock_http.js << 'MOCKEOF'
const http = require('http');
const fs = require('fs');
const tarball = fs.readFileSync('/tmp/dynamodb_local_fake.tar.gz');
const originalGet = http.get;
http.get = function(url, options, callback) {
    if (typeof url === 'string' && url.includes('dynamodb_local_latest.tar.gz')) {
        // Simulate a successful HTTP 200 response with tar.gz body
        const mockRes = {
            statusCode: 200,
            headers: { 'content-length': tarball.length.toString() },
            pipe: function(dest) {
                dest.write(tarball);
                dest.emit('data', tarball);
                dest.emit('end');
                return dest;
            }
        };
        if (callback) callback(mockRes);
        return { on: function(evt, fn) { if (evt === 'error') { /* noop */ } return this; } };
    }
    return originalGet.apply(http, arguments);
};
MOCKEOF

# Run only the specific test file from this PR, with HTTP mock preloaded
npx mocha --require /tmp/mock_http.js test/index.test.js --reporter spec --timeout 30000
test_status=$?

if [ $test_status -eq 0 ]; then
  echo 1 > /logs/verifier/reward.txt
else
  echo 0 > /logs/verifier/reward.txt
fi
exit "$test_status"

